import random


def strategy(history, rng):
    # Independent strategy for iterated Prisoner's Dilemma.
    # Goal: exploit conditional cooperators while avoiding needless punishment spirals.

    n = len(history)
    if n == 0:
        return 'C'

    # Counts from this match.
    my_c = 0
    my_d = 0
    op_c = 0
    op_d = 0
    cc = 0
    cd = 0
    dc = 0
    dd = 0

    for my, op in history:
        if my == 'C':
            my_c += 1
        else:
            my_d += 1

        if op == 'C':
            op_c += 1
        else:
            op_d += 1

        if my == 'C' and op == 'C':
            cc += 1
        elif my == 'C' and op == 'D':
            cd += 1
        elif my == 'D' and op == 'C':
            dc += 1
        else:
            dd += 1

    # Last few actions, useful for responsive decisions.
    last_my, last_op = history[-1]
    recent = history[-6:] if n >= 6 else history
    recent_op_c = sum(1 for _, op in recent if op == 'C')
    recent_my_d = sum(1 for my, _ in recent if my == 'D')

    op_coop_rate = op_c / float(n)
    my_coop_rate = my_c / float(n)

    # Detect likely forgiving, cooperative, or punitive opponents.
    # Very cooperative opponents are worth cooperating with, but we still probe
    # occasionally to collect DC=5 payoff.
    if n >= 8 and op_coop_rate >= 0.85:
        if n % 7 == 0 and last_op == 'C':
            return 'D'
        return 'C'

    # If opponent almost always defects, best response is always defect.
    if n >= 5 and op_coop_rate <= 0.15:
        return 'D'

    # If we are being punished heavily after defecting, return to cooperation
    # to avoid long DD=1 streaks.
    if dc >= 1 and last_op == 'D' and dd >= 2:
        if rng.random() < 0.65:
            return 'C'

    # If opponent is mostly cooperative but we have recently exploited, calm down.
    if op_coop_rate >= 0.65 and last_op == 'D' and recent_op_c >= 3:
        return 'C'

    # Tit-for-tat-like core with occasional forgiveness and controlled probing.
    if last_op == 'C':
        # Probe only when we have a strong cooperative cushion.
        if n >= 12 and op_coop_rate >= 0.75 and my_coop_rate >= 0.65:
            if n % 11 == 0 and rng.random() < 0.35:
                return 'D'
        return 'C'

    # Opponent just defected.
    if n >= 3:
        # If this looks like an isolated defection against mostly cooperation,
        # retaliate briefly then forgive.
        if op_coop_rate >= 0.55 and recent_op_c >= 2:
            if rng.random() < 0.35:
                return 'C'
            return 'D'

        # If opponent defects often, defect more persistently.
        if op_coop_rate < 0.45:
            if rng.random() < 0.15:
                return 'C'
            return 'D'

    # Default retaliation, with small forgiveness.
    if rng.random() < 0.12:
        return 'C'
    return 'D'
